export function getCourseObjectives (classId) {
  return classId === 'intro-research' ? introResearchObjectives.courseObjectives : []
}

/** Objectives for one Assignment Help id (e.g. 'ir-methods-draft'), with the supported course objectives expanded. */
export function getAssignmentObjectives (classId, assignmentId) {
  if (classId !== 'intro-research') return null
  const a = introResearchObjectives.assignments[assignmentId]
  if (!a) return null
  const byId = Object.fromEntries(introResearchObjectives.courseObjectives.map((c) => [c.id, c]))
  return { objectives: a.objectives, supports: a.supports.map((id) => byId[id]).filter(Boolean) }
}

/** Assignment Help ids (and titles) that support a course objective. */
export function assignmentsForObjective (objectiveId) {
  return Object.entries(introResearchObjectives.assignments)
    .filter(([, a]) => a.supports.includes(objectiveId))
    .map(([id, a]) => ({ id, title: a.title }))
}

export function weeksForObjective (objectiveId) {
  return Object.entries(introResearchObjectives.weeks)
    .filter(([, w]) => w.supports.includes(objectiveId))
    .map(([n, w]) => ({ number: Number(n), title: w.title }))
}

